import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Validate user registration with unique email and strong password.
 *
 * This test covers:
 *
 * - Generating a random unique email address (valid format, guaranteed new each
 *   run)
 * - Generating a strong password (at least 8 characters, contains letters and
 *   numbers)
 * - Providing required session context: href and referrer (valid URIs)
 * - Submitting the registration request via /auth/user/join
 * - Verifying response includes all allowed fields (id, email, created_at,
 *   updated_at, token)
 * - Ensuring token contains access, refresh, expired_at, and refreshable_until
 *   fields
 * - Confirming type and format conformance for all response fields
 * - Ensuring server enforces email uniqueness, password minimum requirements, and
 *   allows only permitted data output
 *
 * No pre-existing user data or dependencies required. This is a stand-alone
 * scenario.
 */
export async function test_api_user_registration_unique_email_and_strong_password(
  connection: api.IConnection,
) {
  // Generate test data
  const email = typia.random<string & tags.Format<"email">>();
  // Generate strong password - 8+ alphanumeric characters
  const passwordRaw = RandomGenerator.alphaNumeric(12);
  // Ensure at least one letter and one number (by regex)
  const password =
    /[a-z]/i.test(passwordRaw) && /[0-9]/.test(passwordRaw)
      ? passwordRaw
      : passwordRaw.slice(0, 8) + "Ab1";
  const href = "https://test.example.com/register";
  const referrer = "https://test.example.com/login";
  // Compose registration request
  const body = {
    email,
    password: password satisfies string & tags.MinLength<8> as string,
    href,
    referrer,
  } satisfies ITodoUser.IJoin;
  // Perform registration
  const result = await api.functional.auth.user.join(connection, {
    body,
  });
  typia.assert(result);
  // Check response fields
  TestValidator.predicate(
    "response contains all allowed fields",
    "id" in result &&
      "email" in result &&
      "created_at" in result &&
      "updated_at" in result &&
      "token" in result,
  );
  // Validate token fields
  const { token } = result;
  TestValidator.predicate(
    "token contains access, refresh, expired_at, refreshable_until",
    "access" in token &&
      "refresh" in token &&
      "expired_at" in token &&
      "refreshable_until" in token,
  );
  typia.assert(token);
  // Validate id format
  TestValidator.predicate(
    "id is a UUID",
    typeof result.id === "string" &&
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
        result.id,
      ),
  );
  // Validate email matches input
  TestValidator.equals("email matches", result.email, email);
  // Validate created_at/updated_at are ISO strings
  TestValidator.predicate(
    "created_at and updated_at are valid ISO date strings",
    typeof result.created_at === "string" &&
      !isNaN(Date.parse(result.created_at)) &&
      typeof result.updated_at === "string" &&
      !isNaN(Date.parse(result.updated_at)),
  );
  // Validate password is not leaked in response
  TestValidator.predicate(
    "response does not leak password",
    !("password" in result),
  );
  // Re-registering same email must fail
  await TestValidator.error(
    "duplicate email registration should fail",
    async () => {
      await api.functional.auth.user.join(connection, {
        body,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Validate rejection of duplicate user registration by email uniqueness
 * constraint.
 *
 * This test ensures that the registration endpoint `/auth/user/join` enforces
 * the uniqueness of email addresses. It first registers a new user with
 * randomly generated valid data, and then attempts to register a second user
 * using the same email but a different password and context. The registration
 * attempt must fail, demonstrating that the system prevents duplicate email use
 * and never leaks original user information. This is critical for both
 * compliance (email as a unique credential) and user data privacy.
 *
 * Steps:
 *
 * 1. Register a new user with random, valid data.
 * 2. Attempt to register another user with the identical email, new password and
 *    session context.
 * 3. Expect the second registration to be rejected.
 * 4. Ensure no sensitive/original user data is exposed in the rejection.
 */
export async function test_api_user_registration_duplicate_email_rejected(
  connection: api.IConnection,
) {
  // 1. Register a unique user
  const userBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    href: "https://example.com/join",
    referrer: "https://example.com/login",
  } satisfies ITodoUser.IJoin;
  const firstResult = await api.functional.auth.user.join(connection, {
    body: userBody,
  });
  typia.assert(firstResult);

  // 2. Attempt registration with the same email
  const dupUserBody = {
    email: userBody.email,
    password: RandomGenerator.alphaNumeric(14),
    href: "https://example.com/join2",
    referrer: "https://example.com/register",
  } satisfies ITodoUser.IJoin;
  await TestValidator.error(
    "duplicate email registration must be rejected",
    async () => {
      await api.functional.auth.user.join(connection, { body: dupUserBody });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Test that login fails with correct email and invalid password.
 *
 * This test verifies that logging in with the correct email and an incorrect
 * password is properly denied by the /auth/user/login endpoint. It ensures no
 * authentication information is exposed on failure and the error response is
 * generic and privacy-preserving.
 *
 * Steps:
 *
 * 1. Register a new user with /auth/user/join (random email/password, proper
 *    URIs).
 * 2. Attempt to login with correct email but clearly incorrect password (of
 *    minimum valid length).
 * 3. Assert authentication fails, no token or user object is returned, and the
 *    error is generic without revealing credential or existence details.
 */
export async function test_api_user_login_invalid_password_rejected(
  connection: api.IConnection,
) {
  // 1. Register a user
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const password: string & tags.MinLength<8> = RandomGenerator.alphaNumeric(10);
  const joinBody = {
    email,
    password,
    ip: null,
    href: "https://e2e.test/join",
    referrer: "https://e2e.test/login",
  } satisfies ITodoUser.IJoin;
  const registered = await api.functional.auth.user.join(connection, {
    body: joinBody,
  });
  typia.assert(registered);

  // 2. Attempt login with correct email but incorrect password
  const wrongPassword: string & tags.MinLength<8> & tags.MaxLength<128> =
    RandomGenerator.alphaNumeric(12);
  const loginBody = {
    email,
    password: wrongPassword,
    ip: null,
    href: "https://e2e.test/login",
    referrer: "https://e2e.test/join",
  } satisfies ITodoUser.ILogin;
  await TestValidator.error(
    "login with correct email but wrong password should be rejected generically",
    async () => {
      await api.functional.auth.user.login(connection, { body: loginBody });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Test login attempt with non-existent email is rejected generically.
 *
 * This test validates that authentication fails when a user attempts to log in
 * with an email address that does not correspond to any registered account. It
 * ensures that the API returns a generic error, does not expose whether the
 * account exists, and does not distinguish between non-existent and
 * wrong-password cases in the error message or status code.
 *
 * Steps:
 *
 * 1. Generate a random email address that is highly unlikely to exist in the
 *    system.
 * 2. Attempt login with the random email and a valid password.
 * 3. Assert that authentication fails with a generic error and that no sensitive
 *    information about account existence or failure reason is leaked.
 */
export async function test_api_user_login_nonexistent_email_rejected(
  connection: api.IConnection,
) {
  // Step 1: Generate a guaranteed-nonexistent random email
  const bogusEmail =
    `nonexistent+${RandomGenerator.alphaNumeric(12)}@notreal-domain.com` as string &
      tags.Format<"email">;
  // Step 2: Use a syntactically valid password
  const bogusPassword = RandomGenerator.alphaNumeric(12) as string &
    tags.MinLength<8> &
    tags.MaxLength<128>;
  const loginBody = {
    email: bogusEmail,
    password: bogusPassword,
    href: "https://app.wrtn.ai/login", // valid URI
    referrer: "https://app.wrtn.ai/", // valid URI
    ip: null,
  } satisfies ITodoUser.ILogin;
  // Step 3: Attempt login and assert generic error is returned
  await TestValidator.error(
    "login with nonexistent email should fail generically",
    async () => {
      await api.functional.auth.user.login(connection, { body: loginBody });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

export async function test_api_todo_permanent_deletion_by_owner(
  connection: api.IConnection,
) {
  // 1. Register the owner user (User A)
  const joinA = await api.functional.auth.user.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12) as string & tags.MinLength<8>,
      href: "https://test-app/welcome",
      referrer: "https://test-app/landing",
    } satisfies ITodoUser.IJoin,
  });
  typia.assert(joinA);
  const userAId = joinA.id;

  // 2. Create a new todo item as owner
  const todo = await api.functional.todo.user.todos.create(connection, {
    body: {
      description: RandomGenerator.paragraph({ sentences: 3 }),
    } satisfies ITodoTodo.ICreate,
  });
  typia.assert(todo);
  TestValidator.equals(
    "todo ownership is correct after creation",
    todo.user.id,
    userAId,
  );

  // 3. Delete the created todo item as owner
  await api.functional.todo.user.todos.erase(connection, { todoId: todo.id });

  // 4. Attempt to access the deleted todo item (should not be found)
  // As there is no GET endpoint for a specific todo provided, this negative test is omitted.
  // If such endpoint existed (e.g. api.functional.todo.user.todos.at), we would verify it throws.

  // 5. Register a different user (User B) and attempt to delete User A's (already deleted) todo
  const joinB = await api.functional.auth.user.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12) as string & tags.MinLength<8>,
      href: "https://test-app/welcome",
      referrer: "https://test-app/landing",
    } satisfies ITodoUser.IJoin,
  });
  typia.assert(joinB);

  // Switch to User B's session: connection.headers is managed by SDK, no need to manually swap

  // Negative check: User B attempts to delete already deleted todo (should fail with access or missing resource)
  await TestValidator.error(
    "non-owner cannot delete non-existent or foreign todo",
    async () => {
      await api.functional.todo.user.todos.erase(connection, {
        todoId: todo.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Validate that an authenticated user can create a new todo item and all
 * business constraints are enforced.
 *
 * 1. Register and authenticate as a new user using unique credentials.
 * 2. Create a todo item using a valid description (trimmed, 1-255 chars).
 * 3. Assert system-managed fields (id, timestamps, is_completed, ownership,
 *    state).
 * 4. Check that ownership is enforced on created todo (user matches logged-in
 *    account).
 * 5. Verify initial completion state (is_completed = false, completed_at =
 *    null/undefined).
 * 6. The todo must not appear to any user but its owner (privacy enforcement).
 */
export async function test_api_todo_creation_by_authenticated_user(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new user (unique email/password)
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    href: "https://test-app.local/join",
    referrer: "https://test-app.local/welcome",
  } satisfies ITodoUser.IJoin;
  const auth: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: joinBody },
  );
  typia.assert(auth);

  // 2. Create a todo item with a trimmed, valid description
  const todoDescription = RandomGenerator.paragraph({
    sentences: 5,
    wordMin: 4,
    wordMax: 15,
  })
    .trim()
    .substring(0, 255);
  const todoBody = {
    description: todoDescription,
  } satisfies ITodoTodo.ICreate;
  const todo: ITodoTodo = await api.functional.todo.user.todos.create(
    connection,
    { body: todoBody },
  );
  typia.assert(todo);

  // 3. Assert system-managed/ownership fields
  TestValidator.predicate(
    "todo id must be defined",
    typeof todo.id === "string" && todo.id.length > 0,
  );
  TestValidator.predicate(
    "todo user is defined and is object",
    typeof todo.user === "object" && !!todo.user,
  );
  TestValidator.equals(
    "todo user.id matches authorized user id",
    todo.user.id,
    auth.id,
  );
  TestValidator.equals(
    "todo user.email matches join email",
    todo.user.email,
    joinBody.email,
  );
  typia.assert(todo.user);

  TestValidator.predicate(
    "created_at is valid date-time",
    typeof todo.created_at === "string" && todo.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at is valid date-time",
    typeof todo.updated_at === "string" && todo.updated_at.length > 0,
  );

  // 4. Ownership enforcement (todo appears only to owner)
  // (Cannot explicitly check for appearance in owner list here as listing API is not provided)

  // 5. Initial todo state
  TestValidator.equals(
    "todo is initially incomplete",
    todo.is_completed,
    false,
  );
  TestValidator.equals(
    "completed_at should be null or undefined initially",
    todo.completed_at,
    null,
  );

  // 6. Description checks
  TestValidator.predicate(
    "description matches input, is trimmed, and correct length",
    todo.description === todoDescription &&
      todo.description.length >= 1 &&
      todo.description.length <= 255,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoTodo";
import type { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Validate paginated, filtered, and sorted todo list operation for an
 * authenticated user, ensuring only own todos are accessible and
 * pagination/filtering/sorting behave as specified.
 *
 * Steps:
 *
 * 1. Register user and establish authentication session as the test subject.
 * 2. Create a set of todos for the user with varied descriptions, completion
 *    statuses, and created/updated timestamps (simulate history by modifying
 *    timestamps if API supports it).
 * 3. Issue paginated/filtered PATCH requests for: a. Partial description search
 *    (substring in description) b. Filter by is_completed=false c. Date-range
 *    creation filter (created_from, created_to) d. Descending sort by
 *    updated_at e. Combination of the above (e.g., substring AND is_completed
 *    AND date-range) f. Pagination with limit/page and edge case: page with no
 *    results
 * 4. Assert the response contains only the authenticated user's todos with correct
 *    filtering, no leaking of other users' data, correct pagination meta, and
 *    sorted order.
 * 5. Repeat with a second user: create a second account with distinct todos and
 *    confirm original user cannot see these when filtering/paginating their
 *    list.
 */
export async function test_api_user_todo_list_paginated_search_and_filtering(
  connection: api.IConnection,
) {
  // 1. Register first user
  const email1: string = typia.random<string & tags.Format<"email">>();
  const password1: string = RandomGenerator.alphaNumeric(12);
  const joinBody1 = {
    email: email1,
    password: password1,
    href: "https://todo.example.com/register",
    referrer: "https://todo.example.com/",
    ip: undefined,
  } satisfies ITodoUser.IJoin;
  const user1: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: joinBody1 },
  );
  typia.assert(user1);

  // 2. Create a variety of todos for this user
  const descriptions = [
    "buy groceries for mom",
    "pay electricity bill",
    "start typescript project",
    "groceries: get apples, bananas, bread",
    "complete e2e testing guide",
    "schedule dentist appointment",
    "write weekly report",
    "organize groceries receipts",
    "fix production bug",
    "groceries shopping with kids",
  ];
  // Create 10 todos in varied order and with varied status (complete/incomplete)
  const createdTodos: ITodoTodo[] = [];
  for (let i = 0; i < descriptions.length; ++i) {
    const todo: ITodoTodo = await api.functional.todo.user.todos.create(
      connection,
      {
        body: {
          description: descriptions[i] as string &
            tags.MinLength<1> &
            tags.MaxLength<255>,
        } satisfies ITodoTodo.ICreate,
      },
    );
    typia.assert(todo);
    // For some, mark as completed by creating a new one (simulate using updated_at and is_completed changes by filtering not API update)
    createdTodos.push(todo);
  }

  // Manually adjust completion: mark 3/10 as completed via direct array mutation for test logic (no API method).
  // We'll simulate that some "virtual" todos are complete by setting their is_completed property for test filtering logic
  createdTodos[2] = {
    ...createdTodos[2],
    is_completed: true,
    completed_at: createdTodos[2].updated_at,
  };
  createdTodos[6] = {
    ...createdTodos[6],
    is_completed: true,
    completed_at: createdTodos[6].updated_at,
  };
  createdTodos[8] = {
    ...createdTodos[8],
    is_completed: true,
    completed_at: createdTodos[8].updated_at,
  };

  // 3. Test description substring filter (search)
  const searchTerm = "groceries";
  const searchTodos = createdTodos.filter((t) =>
    t.description.includes(searchTerm),
  );
  const searchResp = await api.functional.todo.user.todos.index(connection, {
    body: { search: searchTerm } satisfies ITodoTodo.IRequest,
  });
  typia.assert(searchResp);
  // Only this user's todos should be present and all descriptions contain the term
  TestValidator.predicate(
    "all results contain search term and belong to user",
    searchResp.data.every(
      (t) => t.description.includes(searchTerm) && t.user_id === user1.id,
    ),
  );

  // 4. Test completion filtering (is_completed=false)
  const incompleteTodos = createdTodos.filter((t) => !t.is_completed);
  const incompleteResp = await api.functional.todo.user.todos.index(
    connection,
    {
      body: { is_completed: false } satisfies ITodoTodo.IRequest,
    },
  );
  typia.assert(incompleteResp);
  TestValidator.equals(
    "filtered todos all incomplete, belong to user",
    incompleteResp.data.map((t) => t.user_id),
    incompleteResp.data.map(() => user1.id),
  );
  TestValidator.predicate(
    "all todos are incomplete",
    incompleteResp.data.every((t) => t.is_completed === false),
  );

  // 5. Test created_from/created_to filter using date range: pick window covering 5 of the todos
  const byDate = createdTodos.slice(3, 8);
  const from = byDate[0].created_at;
  const to = byDate[byDate.length - 1].created_at;
  const dateResp = await api.functional.todo.user.todos.index(connection, {
    body: { created_from: from, created_to: to } satisfies ITodoTodo.IRequest,
  });
  typia.assert(dateResp);
  TestValidator.predicate(
    "all todos in date range, belong to user",
    dateResp.data.every(
      (t) =>
        t.created_at >= from && t.created_at <= to && t.user_id === user1.id,
    ),
  );

  // 6. Test sort descending by updated_at
  const sortedTodos = [...createdTodos].sort((a, b) =>
    b.updated_at.localeCompare(a.updated_at),
  );
  const sortResp = await api.functional.todo.user.todos.index(connection, {
    body: {
      order_by: "updated_at",
      order_desc: true,
    } satisfies ITodoTodo.IRequest,
  });
  typia.assert(sortResp);
  const apiSortedIds = sortResp.data.map((t) => t.id);
  const expectedSortedIds = sortedTodos.map((t) => t.id);
  TestValidator.equals(
    "sorted descending by updated_at",
    apiSortedIds.slice(0, sortResp.pagination.limit),
    expectedSortedIds.slice(0, sortResp.pagination.limit),
  );

  // 7. Combination: search + incomplete + date range
  const comboTodos = incompleteTodos.filter(
    (t) =>
      t.description.includes(searchTerm) &&
      t.created_at >= from &&
      t.created_at <= to,
  );
  const comboResp = await api.functional.todo.user.todos.index(connection, {
    body: {
      search: searchTerm,
      is_completed: false,
      created_from: from,
      created_to: to,
    } satisfies ITodoTodo.IRequest,
  });
  typia.assert(comboResp);
  TestValidator.predicate(
    "combo filter: search, incomplete, date range, correct user only",
    comboResp.data.every(
      (t) =>
        t.description.includes(searchTerm) &&
        !t.is_completed &&
        t.created_at >= from &&
        t.created_at <= to &&
        t.user_id === user1.id,
    ),
  );

  // 8. Pagination and no results
  const limit = 3;
  const pageResp = await api.functional.todo.user.todos.index(connection, {
    body: {
      limit,
      page: 2,
      order_by: "created_at",
      order_desc: true,
    } satisfies ITodoTodo.IRequest,
  });
  typia.assert(pageResp);
  TestValidator.equals(
    "pagination limit respected",
    pageResp.pagination.limit,
    limit,
  );

  // page too high = no results
  const outsidePageResp = await api.functional.todo.user.todos.index(
    connection,
    {
      body: { limit, page: 1000 } satisfies ITodoTodo.IRequest,
    },
  );
  typia.assert(outsidePageResp);
  TestValidator.equals(
    "page with no results returns empty data",
    outsidePageResp.data.length,
    0,
  );

  // 9. Cross-user data privacy: register another user and create todos
  const email2: string = typia.random<string & tags.Format<"email">>();
  const password2: string = RandomGenerator.alphaNumeric(12);
  const joinBody2 = {
    email: email2,
    password: password2,
    href: "https://todo.example.com/register",
    referrer: "https://todo.example.com/",
    ip: undefined,
  } satisfies ITodoUser.IJoin;
  const user2: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: joinBody2 },
  );
  typia.assert(user2);
  for (let i = 0; i < 2; ++i) {
    const _ = await api.functional.todo.user.todos.create(connection, {
      body: {
        description: `other user todo ${i}` as string &
          tags.MinLength<1> &
          tags.MaxLength<255>,
      } satisfies ITodoTodo.ICreate,
    });
    // typia.assert for void return not needed
  }
  // Login back as user1 (original test user)
  await api.functional.auth.user.join(connection, { body: joinBody1 }); // This resets token
  // Confirm none of the second user's todos appear for first user
  const respAfterOther = await api.functional.todo.user.todos.index(
    connection,
    {
      body: {} satisfies ITodoTodo.IRequest,
    },
  );
  typia.assert(respAfterOther);
  TestValidator.predicate(
    "no cross-user data leak: all listed todos belong to user1",
    respAfterOther.data.every((t) => t.user_id === user1.id),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Validate retrieval and access control of todo detail for authenticated users.
 *
 * This test simulates the entire user interaction necessary to access the
 * detail view of a single todo item in a privacy-preserving todo list system.
 * The test sets up two users (A, B) sequentially and ensures full
 * authentication context for each. User A registers, creates a new todo, and
 * then fetches the detail using the GET endpoint with the appropriate ID, while
 * verifying that all expected fields and user summary information are present
 * and accurate. The test also validates that user A cannot fetch any todo
 * belonging to user B, confirming ownership isolation and privacy. It includes
 * assertions for data structure and business logic, such as matching
 * created/updated timestamps, is_completed flag defaulting to false, the
 * presence (or absence) of 'completed_at', and that unauthorized access is
 * handled as not found without leaking item existence.
 */
export async function test_api_user_todo_detail_retrieval(
  connection: api.IConnection,
) {
  // Register User A
  const userA_email = typia.random<string & tags.Format<"email">>();
  const userA_password = RandomGenerator.alphaNumeric(12);
  const userA_href = "https://test-usera.example.com/";
  const userA_referrer = "https://signup.example.com/";
  const userA: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: {
        email: userA_email,
        password: userA_password,
        href: userA_href,
        referrer: userA_referrer,
      } satisfies ITodoUser.IJoin,
    },
  );
  typia.assert(userA);

  // Create a todo for User A
  const descriptionA = RandomGenerator.paragraph({
    sentences: 5,
    wordMin: 3,
    wordMax: 10,
  });
  const todoA: ITodoTodo = await api.functional.todo.user.todos.create(
    connection,
    {
      body: { description: descriptionA } satisfies ITodoTodo.ICreate,
    },
  );
  typia.assert(todoA);

  // Fetch detail for User A's todo
  const fetchedA: ITodoTodo = await api.functional.todo.user.todos.at(
    connection,
    {
      todoId: todoA.id,
    },
  );
  typia.assert(fetchedA);

  // Validate fields are correct and match expected properties
  TestValidator.equals("todo id matches", fetchedA.id, todoA.id);
  TestValidator.equals(
    "description matches",
    fetchedA.description,
    descriptionA,
  );
  TestValidator.equals(
    "is_completed is false after creation",
    fetchedA.is_completed,
    false,
  );
  TestValidator.equals(
    "user summary id matches owner",
    fetchedA.user.id,
    userA.id,
  );
  TestValidator.equals(
    "user summary email matches owner",
    fetchedA.user.email,
    userA.email,
  );
  TestValidator.equals(
    "created_at is correct",
    fetchedA.created_at,
    todoA.created_at,
  );
  TestValidator.equals(
    "updated_at is correct",
    fetchedA.updated_at,
    todoA.updated_at,
  );
  TestValidator.equals(
    "completed_at is undefined/null on creation",
    fetchedA.completed_at,
    todoA.completed_at,
  );

  // Register User B
  const userB_email = typia.random<string & tags.Format<"email">>();
  const userB_password = RandomGenerator.alphaNumeric(12);
  const userB_href = "https://test-userb.example.com/";
  const userB_referrer = "https://signup.example.com/";
  const userB: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: {
        email: userB_email,
        password: userB_password,
        href: userB_href,
        referrer: userB_referrer,
      } satisfies ITodoUser.IJoin,
    },
  );
  typia.assert(userB);

  // Create a todo for User B and verify that UserA cannot access it
  const descriptionB = RandomGenerator.paragraph({
    sentences: 2,
    wordMin: 4,
    wordMax: 8,
  });
  const todoB: ITodoTodo = await api.functional.todo.user.todos.create(
    connection,
    {
      body: { description: descriptionB } satisfies ITodoTodo.ICreate,
    },
  );
  typia.assert(todoB);

  // Switch context back to UserA (by re-authenticating)
  await api.functional.auth.user.join(connection, {
    body: {
      email: userA_email,
      password: userA_password,
      href: userA_href,
      referrer: userA_referrer,
    } satisfies ITodoUser.IJoin,
  });

  // UserA attempts to fetch UserB's todo (should fail with not found or similar privacy-preserving error)
  await TestValidator.error(
    "UserA cannot access UserB's todo detail",
    async () => {
      await api.functional.todo.user.todos.at(connection, { todoId: todoB.id });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Test creation of a todo item by an authenticated user, verifying correct
 * handling of business rules, ownership, and constraints.
 *
 * Steps:
 *
 * 1. Register and authenticate a new user via /auth/user/join.
 * 2. Successfully create a todo with a valid trimmed description (1-255 chars) via
 *    /todo/user/todos.
 *
 *    - Assert description is trimmed, not altered, and saved as provided.
 *    - Assert ownership: todo.user.id equals authenticated user id and is not null.
 *    - Assert completion status is false; completed_at is null/undefined.
 *    - Assert created_at and updated_at fields are valid ISO timestamps and not
 *         empty.
 * 3. Attempt to create with an empty/whitespace-only description.
 *
 *    - Assert error is thrown (using correct type, not sending wrong types).
 * 4. Attempt to create with a too-long description (>255 chars).
 *
 *    - Assert error is thrown.
 * 5. (Simulate quota violation) Attempt to create enough todos to potentially hit
 *    quota, then make one more, and assert error. (Assume system applies
 *    reasonable per-user todo count limit, e.g., 1000; do not hard-code invalid
 *    values, just show logic structure with comment.)
 */
export async function test_api_todo_creation_by_authenticated_user(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new user
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const joinBody = {
    email,
    password,
    href: "https://example.com/register",
    referrer: "https://example.com/landing",
  } satisfies ITodoUser.IJoin;
  const user = await api.functional.auth.user.join(connection, {
    body: joinBody,
  });
  typia.assert(user);

  // 2. Create a todo with valid trimmed description
  const rawDescription = `   ${RandomGenerator.paragraph({ sentences: 4, wordMin: 5, wordMax: 10 })}   `;
  const validDescription = rawDescription.trim();
  const todoBody = {
    description: validDescription as string &
      tags.MinLength<1> &
      tags.MaxLength<255>,
  } satisfies ITodoTodo.ICreate;
  const todo = await api.functional.todo.user.todos.create(connection, {
    body: todoBody,
  });
  typia.assert(todo);

  // 2-1. Field validation
  TestValidator.equals(
    "todo description matches trimmed input",
    todo.description,
    validDescription,
  );
  TestValidator.equals(
    "todo assigned to requesting user",
    todo.user.id,
    user.id,
  );
  TestValidator.equals(
    "completion status is initially false",
    todo.is_completed,
    false,
  );
  TestValidator.equals(
    "completed_at is null or undefined",
    todo.completed_at,
    null,
  );
  TestValidator.predicate(
    "created_at is non-empty ISO string",
    typeof todo.created_at === "string" && todo.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at is non-empty ISO string",
    typeof todo.updated_at === "string" && todo.updated_at.length > 0,
  );

  // 3. Error: empty/whitespace-only description
  await TestValidator.error(
    "cannot create todo with empty description",
    async () => {
      await api.functional.todo.user.todos.create(connection, {
        body: {
          description: " " as string & tags.MinLength<1> & tags.MaxLength<255>,
        } satisfies ITodoTodo.ICreate,
      });
    },
  );

  // 4. Error: description exceeds 255 chars
  const tooLongDescription = "x".repeat(256) as string &
    tags.MinLength<1> &
    tags.MaxLength<255>;
  await TestValidator.error(
    "cannot create todo with overlong description",
    async () => {
      await api.functional.todo.user.todos.create(connection, {
        body: {
          description: tooLongDescription,
        } satisfies ITodoTodo.ICreate,
      });
    },
  );

  // 5. (Simulate quota logic - system enforced, not validated here):
  // Fill up todos up to quota (simulate up to 5 for test speed, document real limit is higher).
  const MAX_TEST_TODOS = 5;
  const testTodos = [] as ITodoTodo[];
  for (let i = 0; i < MAX_TEST_TODOS; ++i) {
    const t = await api.functional.todo.user.todos.create(connection, {
      body: {
        description: RandomGenerator.paragraph({
          sentences: 5,
          wordMin: 3,
          wordMax: 8,
        }) as string & tags.MinLength<1> & tags.MaxLength<255>,
      } satisfies ITodoTodo.ICreate,
    });
    testTodos.push(t);
    typia.assert(t);
  }
  // Try one more, expecting error as if quota is reached (for demonstration only; actual quota may be >5):
  await TestValidator.error(
    "cannot create todo when user quota is exhausted (simulated)",
    async () => {
      await api.functional.todo.user.todos.create(connection, {
        body: {
          description: RandomGenerator.paragraph({
            sentences: 5,
            wordMin: 3,
            wordMax: 8,
          }) as string & tags.MinLength<1> & tags.MaxLength<255>,
        } satisfies ITodoTodo.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Validate that a todo's owner can update the description and completion state
 * of their item, and that business rules for edit constraints are enforced.
 *
 * Test covers:
 *
 * 1. User registration/auth - create user context
 * 2. Create new todo as user
 * 3. Update description to a trimmed, new valid value and verify change
 * 4. Mark todo as completed, verify is_completed true and completed_at set
 * 5. Mark todo as incomplete, verify is_completed false and completed_at cleared
 *    (null)
 * 6. Confirm updated_at advances as expected
 * 7. Attempt to update with empty description -> expect error
 * 8. Attempt to update with too long description -> expect error Business
 *    validation: only the owner can reach this scenario; forbidden/permission
 *    test not required in this function.
 */
export async function test_api_todo_update_by_owner(
  connection: api.IConnection,
) {
  // Step 1: Register/authenticate as new user
  const email = `${RandomGenerator.alphabets(10)}@example.com`;
  const password = RandomGenerator.alphaNumeric(10) + "1A";
  const joinBody = {
    email,
    password: password satisfies string as string,
    href: "https://test.com/register",
    referrer: "https://test.com/",
  } satisfies ITodoUser.IJoin;
  const user = await api.functional.auth.user.join(connection, {
    body: joinBody,
  });
  typia.assert(user);

  // Step 2: Create a todo as user
  const initialDescription = RandomGenerator.paragraph({
    sentences: 4,
    wordMin: 3,
    wordMax: 8,
  }).trim();
  const todo = await api.functional.todo.user.todos.create(connection, {
    body: { description: initialDescription } satisfies ITodoTodo.ICreate,
  });
  typia.assert(todo);
  TestValidator.equals(
    "created description matches",
    todo.description,
    initialDescription,
  );
  TestValidator.predicate(
    "created todo incomplete",
    todo.is_completed === false &&
      (todo.completed_at === null || todo.completed_at === undefined),
  );

  // Step 3: update description with whitespace (should be trimmed)
  const updatedDescription = `  ${RandomGenerator.paragraph({ sentences: 2, wordMin: 3, wordMax: 8 })}  `;
  const trimmed = updatedDescription.trim();
  const updatedTodo = await api.functional.todo.user.todos.update(connection, {
    todoId: todo.id,
    body: { description: updatedDescription } satisfies ITodoTodo.IUpdate,
  });
  typia.assert(updatedTodo);
  TestValidator.equals(
    "trimmed description updated",
    updatedTodo.description,
    trimmed,
  );
  TestValidator.predicate(
    "updated_at advanced after editing description",
    updatedTodo.updated_at > todo.updated_at,
  );

  // Step 4: mark as completed
  const completedTodo = await api.functional.todo.user.todos.update(
    connection,
    {
      todoId: todo.id,
      body: { is_completed: true } satisfies ITodoTodo.IUpdate,
    },
  );
  typia.assert(completedTodo);
  TestValidator.equals(
    "todo marked completed",
    completedTodo.is_completed,
    true,
  );
  TestValidator.predicate(
    "completed_at is set",
    completedTodo.completed_at !== null &&
      completedTodo.completed_at !== undefined,
  );

  // Step 5: mark back as incomplete
  const incompleteTodo = await api.functional.todo.user.todos.update(
    connection,
    {
      todoId: todo.id,
      body: { is_completed: false } satisfies ITodoTodo.IUpdate,
    },
  );
  typia.assert(incompleteTodo);
  TestValidator.equals(
    "todo marked incomplete",
    incompleteTodo.is_completed,
    false,
  );
  TestValidator.equals(
    "completed_at cleared",
    incompleteTodo.completed_at,
    null,
  );
  TestValidator.predicate(
    "updated_at advances after marking incomplete",
    incompleteTodo.updated_at > completedTodo.updated_at,
  );

  // Step 6: failure - empty description
  await TestValidator.error("rejects empty description", async () => {
    await api.functional.todo.user.todos.update(connection, {
      todoId: todo.id,
      body: { description: "   " } satisfies ITodoTodo.IUpdate,
    });
  });

  // Step 7: failure - overly long description (> 255 chars after trim)
  const tooLong = RandomGenerator.alphabets(260);
  await TestValidator.error("rejects too long description", async () => {
    await api.functional.todo.user.todos.update(connection, {
      todoId: todo.id,
      body: { description: tooLong } satisfies ITodoTodo.IUpdate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Test that a registered user can retrieve their own user detail successfully,
 * and cannot access others' details.
 *
 * Steps:
 *
 * 1. Register a new user (join) and authenticate to obtain session and id.
 * 2. Retrieve user details for self (expect success and field match).
 * 3. Register a second user (join) with a different email.
 * 4. While authenticated as the first user, attempt to access the second user's
 *    detail (expect error).
 */
export async function test_api_todo_user_detail_self_profile_access_success(
  connection: api.IConnection,
) {
  // 1. Register a new user
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    href: "https://test-href.example.com/register",
    referrer: "https://test-href.example.com/landing",
  } satisfies ITodoUser.IJoin;
  const auth: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: joinRequest },
  );
  typia.assert(auth);

  // 2. Retrieve own user detail
  const userDetail: ITodoUser = await api.functional.todo.user.users.at(
    connection,
    { userId: auth.id },
  );
  typia.assert(userDetail);

  // Validate retrieved fields match registration information
  TestValidator.equals("user id matches", userDetail.id, auth.id);
  TestValidator.equals("user email matches", userDetail.email, auth.email);
  TestValidator.equals(
    "created_at matches",
    userDetail.created_at,
    auth.created_at,
  );
  TestValidator.equals(
    "updated_at matches",
    userDetail.updated_at,
    auth.updated_at,
  );

  // 3. Register a second user (to test access control)
  const joinRequest2 = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    href: "https://test-href.example.com/register2",
    referrer: "https://test-href.example.com/landing2",
  } satisfies ITodoUser.IJoin;
  const auth2: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: joinRequest2 },
  );
  typia.assert(auth2);

  // 4. Attempt to get second user's detail as first user (should fail)
  await TestValidator.error("cannot access other user's detail", async () => {
    await api.functional.todo.user.users.at(connection, { userId: auth2.id });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoUserSession";
import type { ITodoUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUserSession";

/**
 * List and search all sessions for a todo user account (public index).
 *
 * Validates unauthenticated access, pagination, expiry filters, and correctness
 * of summary session metadata, with edge cases for zero/many/mixed-expiry
 * sessions.
 */
export async function test_api_todo_user_sessions_paginated_index_public_access(
  connection: api.IConnection,
) {
  // Create a random userId for query
  const userId = typia.random<string & tags.Format<"uuid">>();

  // --- Case 1: No filter, expect an empty or default result for a new user ---
  const output_no_sessions = await api.functional.todo.users.sessions.index(
    connection,
    {
      userId,
      body: {},
    },
  );
  typia.assert(output_no_sessions);
  TestValidator.equals(
    "no sessions on new user",
    output_no_sessions.data.length,
    0,
  );

  // --- Case 2: Many sessions test (simulate multiple sessions with various expired_at) ---
  // We'll query the API repeatedly to cover paging and filtering logic, no data setup required since endpoint is public/audit-read-only.
  // Full page of active/expired sessions, page size limits, expired/all/active filters, date ranges

  // Use pagination (limit: 3), expect correct records property matches data length
  const output_paged = await api.functional.todo.users.sessions.index(
    connection,
    {
      userId,
      body: { page: 1, limit: 3 },
    },
  );
  typia.assert(output_paged);
  TestValidator.equals(
    "pagination data length matches",
    output_paged.data.length,
    Math.min(output_paged.pagination.limit, output_paged.pagination.records),
  );
  TestValidator.predicate(
    "pagination current page is 1",
    output_paged.pagination.current === 1,
  );
  TestValidator.predicate(
    "pagination limit within allowed range",
    output_paged.pagination.limit >= 1 && output_paged.pagination.limit <= 100,
  );
  TestValidator.predicate(
    "pagination record count >= 0",
    output_paged.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages >= 0",
    output_paged.pagination.pages >= 0,
  );

  // If there are sessions, check summary fields for one
  if (output_paged.data.length > 0) {
    const first = output_paged.data[0];
    typia.assert(first);
    TestValidator.predicate(
      "session id is uuid",
      typeof first.id === "string" && /^[0-9a-f\-]{36}$/.test(first.id),
    );
    TestValidator.predicate(
      "todo_user_id matches",
      first.todo_user_id === userId,
    );
    TestValidator.predicate("ip is string", typeof first.ip === "string");
    TestValidator.predicate(
      "created_at is iso",
      typeof first.created_at === "string" && /T/.test(first.created_at),
    );
    TestValidator.predicate(
      "href is uri",
      typeof first.href === "string" && first.href.startsWith("http"),
    );
    TestValidator.predicate(
      "referrer is uri",
      typeof first.referrer === "string" && first.referrer.startsWith("http"),
    );
    // expired_at may be null, undefined, or date-time string
    if (first.expired_at !== null && first.expired_at !== undefined) {
      TestValidator.predicate(
        "expired_at is iso string",
        typeof first.expired_at === "string" && /T/.test(first.expired_at),
      );
    }
  }

  // --- Case 3: Filter by expired: true ---
  const output_expired = await api.functional.todo.users.sessions.index(
    connection,
    {
      userId,
      body: { expired: true },
    },
  );
  typia.assert(output_expired);
  TestValidator.predicate(
    "all returned are expired",
    output_expired.data.every(
      (s) => s.expired_at !== null && s.expired_at !== undefined,
    ),
  );

  // --- Case 4: Filter by expired: false ---
  const output_active = await api.functional.todo.users.sessions.index(
    connection,
    {
      userId,
      body: { expired: false },
    },
  );
  typia.assert(output_active);
  TestValidator.predicate(
    "all returned are active",
    output_active.data.every(
      (s) => s.expired_at === null || s.expired_at === undefined,
    ),
  );

  // --- Case 5: Date range filters ---
  // Get all first, then test date-range filter using created_at window if any
  if (output_paged.data.length > 0) {
    const first = output_paged.data[0];
    const created_from = first.created_at;
    // Date range: only sessions created at or after the first
    const output_date_range = await api.functional.todo.users.sessions.index(
      connection,
      {
        userId,
        body: { created_from },
      },
    );
    typia.assert(output_date_range);
    TestValidator.predicate(
      "all sessions created_at >= created_from",
      output_date_range.data.every((s) => s.created_at >= created_from),
    );
  }

  // --- Case 6: Public access/no authentication ---
  // Simulate an unauthenticated connection
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  const output_public = await api.functional.todo.users.sessions.index(
    unauthConn,
    {
      userId,
      body: {},
    },
  );
  typia.assert(output_public);
  TestValidator.equals(
    "unauthenticated access yields valid result",
    output_public.pagination.current,
    1,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITodoUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUserSession";

/**
 * Verify public access to session detail retrieval for a todo user session.
 *
 * This test performs the following steps:
 *
 * 1. Uses random UUIDs for userId and sessionId to request a session detail
 *    (likely not found). Expects error handling (e.g., not found/permission
 *    error).
 * 2. Generates a valid mock session via typia, then attempts retrieval by
 *    userId/sessionId. Verifies all returned fields (id, todo_user_id, ip,
 *    href, referrer, created_at, expired_at) are present and correctly
 *    typed/formatted. Ensures expired_at is either a date-time string or
 *    null/undefined according to session status.
 * 3. Simulates expired vs active session: fetches with expired_at set and not set.
 *    Verifies that the expired_at field reflects the correct expiration state
 *    and is correctly reflected in API response.
 *
 * No authentication or POST/PUT operations are used. Endpoint must be
 * public-read and read-only.
 */
export async function test_api_todo_user_sessions_single_session_detail_public_access(
  connection: api.IConnection,
) {
  // 1. Fetch with likely nonexistent UUIDs
  const notFoundUserId = typia.random<string & tags.Format<"uuid">>();
  const notFoundSessionId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "should error for non-existent user/session UUID",
    async () => {
      await api.functional.todo.users.sessions.at(connection, {
        userId: notFoundUserId,
        sessionId: notFoundSessionId,
      });
    },
  );

  // 2. Generate a random valid session, fetch, and check fields
  // Use simulate:true to guarantee session exists for fetch
  const simulatedConnection: api.IConnection = {
    ...connection,
    simulate: true,
  };
  const session = await api.functional.todo.users.sessions.at(
    simulatedConnection,
    {
      userId: typia.random<string & tags.Format<"uuid">>(),
      sessionId: typia.random<string & tags.Format<"uuid">>(),
    },
  );
  typia.assert<ITodoUserSession>(session);
  TestValidator.predicate(
    "session.id is non-empty uuid string",
    typeof session.id === "string" && session.id.length > 0,
  );
  TestValidator.predicate(
    "session.todo_user_id matches uuid",
    typeof session.todo_user_id === "string" && session.todo_user_id.length > 0,
  );
  TestValidator.predicate(
    "session.ip is defined and string",
    typeof session.ip === "string",
  );
  TestValidator.predicate(
    "session.href is string",
    typeof session.href === "string",
  );
  TestValidator.predicate(
    "session.referrer is string",
    typeof session.referrer === "string",
  );
  TestValidator.predicate(
    "session.created_at is non-empty string",
    typeof session.created_at === "string" && session.created_at.length > 0,
  );
  if (session.expired_at !== null && session.expired_at !== undefined) {
    TestValidator.predicate(
      "session.expired_at is string when expired",
      typeof session.expired_at === "string" && session.expired_at.length > 0,
    );
  }

  // 3. Simulate expired session: set expired_at, check retrieval
  // For simulate mode, generate a session with expired_at set (typia.random)
  const expiredSession: ITodoUserSession = {
    ...typia.random<ITodoUserSession>(),
    expired_at: new Date().toISOString(),
  };
  // Simulate retrieval with known values in simulate mode
  const expiredSessionResult = await api.functional.todo.users.sessions.at(
    simulatedConnection,
    {
      userId: expiredSession.todo_user_id,
      sessionId: expiredSession.id,
    },
  );
  typia.assert<ITodoUserSession>(expiredSessionResult);
  TestValidator.equals(
    "expired_at matches forced value on expired session",
    expiredSessionResult.expired_at,
    expiredSession.expired_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Validate successful user session refresh with a valid token.
 *
 * 1. Register a new user and obtain initial authorized session with tokens.
 * 2. Compose a proper token refresh request using the issued refresh token and
 *    required session context fields.
 * 3. POST /auth/user/refresh with the refresh payload.
 * 4. Verify the response is a valid IAuthorized structure (typia.assert).
 * 5. Confirm new tokens are issued (compare to originals: both token.access and
 *    token.refresh are different).
 * 6. User details are only those permitted (id, email, created_at, updated_at,
 *    token) with correct types (no extra exposure).
 * 7. Timestamps and tokens are valid.
 * 8. Ensure privacy and authentication compliance (no leakage of sensitive
 *    fields).
 */
export async function test_api_user_session_refresh_with_valid_token(
  connection: api.IConnection,
) {
  // Step 1: Register user and get initial tokens
  const userJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    ip: null,
    href: "https://example.com/onboarding",
    referrer: "https://example.com/landing-page",
  } satisfies ITodoUser.IJoin;
  const initialAuth = await api.functional.auth.user.join(connection, {
    body: userJoinBody,
  });
  typia.assert(initialAuth);

  // Step 2: Prepare refresh payload
  const refreshPayload = {
    refresh_token: initialAuth.token.refresh,
    ip: null,
    href: "https://example.com/refresh-token",
    referrer: "https://example.com/onboarding",
  } satisfies ITodoUser.IRefresh;

  // Step 3: POST to /auth/user/refresh
  const refreshedAuth = await api.functional.auth.user.refresh(connection, {
    body: refreshPayload,
  });
  typia.assert(refreshedAuth);

  // Step 4: Check response fields and token renewal
  TestValidator.predicate(
    "id is a uuid",
    typeof refreshedAuth.id === "string" &&
      refreshedAuth.id.length === initialAuth.id.length &&
      refreshedAuth.id !== "",
  );
  TestValidator.equals(
    "email matches original",
    refreshedAuth.email,
    initialAuth.email,
  );
  TestValidator.equals("id matches original", refreshedAuth.id, initialAuth.id);
  TestValidator.notEquals(
    "refreshed token.access must change",
    refreshedAuth.token.access,
    initialAuth.token.access,
  );
  TestValidator.notEquals(
    "refreshed token.refresh must change",
    refreshedAuth.token.refresh,
    initialAuth.token.refresh,
  );
  TestValidator.predicate(
    "access token string is valid",
    typeof refreshedAuth.token.access === "string" &&
      refreshedAuth.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token string is valid",
    typeof refreshedAuth.token.refresh === "string" &&
      refreshedAuth.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "access token expiration is ISO 8601",
    typeof refreshedAuth.token.expired_at === "string" &&
      refreshedAuth.token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "refresh token expiration is ISO 8601",
    typeof refreshedAuth.token.refreshable_until === "string" &&
      refreshedAuth.token.refreshable_until.length > 0,
  );

  // Step 5: Ensure only expected fields are present (privacy check)
  const expectedFields = ["id", "email", "created_at", "updated_at", "token"];
  TestValidator.equals(
    "No extraneous user fields in response",
    Object.keys(refreshedAuth).sort(),
    expectedFields.sort(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Test that attempting to refresh a session with an expired or invalid refresh
 * token fails gracefully without exposing sensitive information or user state.
 *
 * Steps:
 *
 * 1. Register a new user to obtain a valid token for context.
 * 2. Attempt session refresh with an obviously invalid refresh token (random, not
 *    issued by system).
 * 3. Assert the API call fails (error is thrown), without revealing user details,
 *    access/refresh tokens, or new session creation. No sensitive or system
 *    data should be present in the error response.
 * 4. Confirm only the minimal privacy-compliant error information is delivered.
 */
export async function test_api_user_session_refresh_with_expired_or_invalid_token(
  connection: api.IConnection,
) {
  // Step 1. Register a new user
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string & tags.MinLength<8>,
    ip: undefined,
    href: "https://example.com/register",
    referrer: "https://example.com/landing",
  } satisfies ITodoUser.IJoin;
  const authorized = await api.functional.auth.user.join(connection, {
    body: joinBody,
  });
  typia.assert(authorized);

  // Step 2. Attempt to refresh session with a definitely invalid refresh token
  const refreshBody = {
    refresh_token: RandomGenerator.alphaNumeric(32) as string &
      tags.MinLength<16> &
      tags.MaxLength<512>,
    ip: undefined,
    href: "https://example.com/account",
    referrer: "https://example.com/login",
  } satisfies ITodoUser.IRefresh;

  await TestValidator.error(
    "refresh with invalid token must fail and leak no sensitive information",
    async () => {
      await api.functional.auth.user.refresh(connection, { body: refreshBody });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Validate password reset initiation for a valid (registered) email.
 *
 * This test ensures that invoking the password reset-request endpoint with a
 * valid, registered user email (from a freshly registered user) returns a
 * generic acceptance response without leaking any information about whether the
 * email is actually registered. It must always respond with { success: true }
 * for privacy. No user/account state changes are expected at this stage.
 *
 * 1. Register a new user (dependency) to obtain an existing email.
 * 2. Call the password reset-request endpoint with that registered email.
 * 3. Assert that the API response is { success: true } (generic acceptance).
 * 4. Confirm response is of ITodoUser.IResetPasswordResponse and contains no
 *    information about whether the email exists.
 * 5. No assertions about user/account state required.
 */
export async function test_api_user_password_reset_request_valid_email(
  connection: api.IConnection,
) {
  // 1. Register a user to create a known email
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8>>(),
    href: "https://app.example.com/join",
    referrer: "https://app.example.com/welcome",
  } satisfies ITodoUser.IJoin;
  const user = await api.functional.auth.user.join(connection, {
    body: joinBody,
  });
  typia.assert(user);

  // 2. Initiate password reset-request for the registered email
  const resetBody = {
    email: joinBody.email,
  } satisfies ITodoUser.IResetPasswordRequest;
  const output =
    await api.functional.auth.user.password.reset_request.resetPassword(
      connection,
      { body: resetBody },
    );
  typia.assert(output);

  // 3. Check response: must always be { success: true } (never leak if email exists)
  TestValidator.equals(
    "reset-request responds with generic success",
    output.success,
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Test password reset initiation with an unknown (unregistered) email address.
 *
 * Business context: This ensures the password reset endpoint does not reveal
 * whether an email exists in the database, preserving user privacy and
 * preventing user enumeration attacks.
 *
 * Test Steps:
 *
 * 1. Generate a random email address that is extremely unlikely to exist in the
 *    system.
 * 2. Submit a reset password request with this email.
 * 3. Validate that the response follows the generic success response pattern
 *    (i.e., { success: true }) regardless of the actual user existence.
 * 4. Confirm no error or indication is given about the existence or absence of the
 *    account associated with that email.
 * 5. (Negative assurance): Repeated requests with arbitrary unused emails always
 *    return the same generic success pattern without revealing information
 *    about system state or user records.
 */
export async function test_api_user_password_reset_request_unknown_email(
  connection: api.IConnection,
) {
  // 1. Generate a random email address unlikely to exist
  const unusedEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  // 2. Submit a password reset initiation request
  const requestBody = {
    email: unusedEmail,
  } satisfies ITodoUser.IResetPasswordRequest;
  const response: ITodoUser.IResetPasswordResponse =
    await api.functional.auth.user.password.reset_request.resetPassword(
      connection,
      { body: requestBody },
    );
  typia.assert(response);

  // 3. Validate the response: always generic (success: true)
  TestValidator.equals(
    "password reset request for unknown email always succeeds generically",
    response.success,
    true,
  );

  // 4-5. Repeat with another random, highly unlikely email to double-check behavior
  const anotherUnusedEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const anotherRequestBody = {
    email: anotherUnusedEmail,
  } satisfies ITodoUser.IResetPasswordRequest;
  const repeatResponse: ITodoUser.IResetPasswordResponse =
    await api.functional.auth.user.password.reset_request.resetPassword(
      connection,
      { body: anotherRequestBody },
    );
  typia.assert(repeatResponse);
  TestValidator.equals(
    "repeated unknown email request still returns generic success",
    repeatResponse.success,
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Validate updating a user's email and password via the update endpoint.
 *
 * 1. Register user1 via join, save its id, token, and initial info for comparison.
 * 2. Register user2 to be used for email conflict testing.
 * 3. Update user1's email only and check updated_at changes and data reflected.
 * 4. Update user1's password only (new strong password), check updated_at changes.
 * 5. Update both email and password in a single call and verify immediate
 *    reflection.
 * 6. Attempt to update user1's email to user2's email and confirm proper error.
 * 7. Attempt to update non-allowed fields; verify they are ignored.
 * 8. Confirm that after a password change, old credentials can no longer
 *    authenticate.
 * 9. After each update, verify changes are reflected in responses.
 *
 * Assumes: There is no dedicated 'get' endpoint; updates confirmed via
 * responses and authentication checks.
 */
export async function test_api_todo_user_update_basic_info(
  connection: api.IConnection,
) {
  // 1. Register user1
  const user1_email = typia.random<string & tags.Format<"email">>();
  const user1_password = RandomGenerator.alphaNumeric(12);
  const user1_join_input = {
    email: user1_email,
    password: user1_password,
    href: "https://test.local/register",
    referrer: "https://test.local/",
  } satisfies ITodoUser.IJoin;
  const user1_auth = await api.functional.auth.user.join(connection, {
    body: user1_join_input,
  });
  typia.assert(user1_auth);
  const user1_id = user1_auth.id;
  const user1_token: IAuthorizationToken = user1_auth.token;
  const user1_initial_updated_at = user1_auth.updated_at;

  // 2. Register user2 for email conflict
  const user2_email = typia.random<string & tags.Format<"email">>();
  const user2_password = RandomGenerator.alphaNumeric(12);
  const user2_join_input = {
    email: user2_email,
    password: user2_password,
    href: "https://test.local/register",
    referrer: "https://test.local/",
  } satisfies ITodoUser.IJoin;
  const user2_auth = await api.functional.auth.user.join(
    { ...connection, headers: {} }, // clean unauth connection
    { body: user2_join_input },
  );
  typia.assert(user2_auth);
  const user2_id = user2_auth.id;

  // 3. Update email only
  const new_email = typia.random<string & tags.Format<"email">>();
  const update_email_input = { email: new_email } satisfies ITodoUser.IUpdate;
  const updated_user1_email = await api.functional.todo.user.users.update(
    connection,
    { userId: user1_id, body: update_email_input },
  );
  typia.assert(updated_user1_email);
  TestValidator.notEquals(
    "updated_at changes after email update",
    updated_user1_email.updated_at,
    user1_initial_updated_at,
  );
  TestValidator.equals("email updated", updated_user1_email.email, new_email);

  // 4. Update password only
  const new_password = RandomGenerator.alphaNumeric(15);
  const update_password_input = {
    password: new_password,
  } satisfies ITodoUser.IUpdate;
  const updated_user1_pass = await api.functional.todo.user.users.update(
    connection,
    { userId: user1_id, body: update_password_input },
  );
  typia.assert(updated_user1_pass);
  TestValidator.notEquals(
    "updated_at changes after password update",
    updated_user1_pass.updated_at,
    updated_user1_email.updated_at,
  );
  TestValidator.equals(
    "email unchanged after password update",
    updated_user1_pass.email,
    new_email,
  );

  // 5. Update both email & password in one call
  const both_email = typia.random<string & tags.Format<"email">>();
  const both_password = RandomGenerator.alphaNumeric(16);
  const update_both_input = {
    email: both_email,
    password: both_password,
  } satisfies ITodoUser.IUpdate;
  const updated_user1_both = await api.functional.todo.user.users.update(
    connection,
    { userId: user1_id, body: update_both_input },
  );
  typia.assert(updated_user1_both);
  TestValidator.equals(
    "email updated with both-field update",
    updated_user1_both.email,
    both_email,
  );
  TestValidator.notEquals(
    "updated_at updates for both change",
    updated_user1_both.updated_at,
    updated_user1_pass.updated_at,
  );

  // 6. Attempt to update user1 email to user2's email (should fail)
  await TestValidator.error("email conflict rejected", async () => {
    await api.functional.todo.user.users.update(connection, {
      userId: user1_id,
      body: { email: user2_email } satisfies ITodoUser.IUpdate,
    });
  });

  // 7. Non-allowed fields ignored (e.g., system field)
  const non_allowed_input: ITodoUser.IUpdate & {
    id?: string;
    created_at?: string;
    updated_at?: string;
  } = {
    email: typia.random<string & tags.Format<"email">>(),
    id: typia.random<string & tags.Format<"uuid">>(),
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  const updated_user_non_allowed = await api.functional.todo.user.users.update(
    connection,
    { userId: user1_id, body: non_allowed_input },
  );
  typia.assert(updated_user_non_allowed);
  TestValidator.equals(
    "system fields not overwritten",
    updated_user_non_allowed.id,
    user1_id,
  );

  // 8. Confirm old password can't be used after password change
  await TestValidator.error(
    "cannot login with old password after change",
    async () => {
      await api.functional.auth.user.join(
        { ...connection, headers: {} },
        {
          body: {
            email: both_email,
            password: new_password,
            href: "https://test.local/login",
            referrer: "https://test.local/",
          } satisfies ITodoUser.IJoin,
        },
      );
    },
  );

  // 9. (No get endpoint) All changes checked by returned entity, already covered above.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * E2E scenario: Ensure complete user deletion and cascade in Todo List app.
 *
 * This test registers two users: the main (to be deleted) and a control user.
 * The main user authenticates, performs self-deletion, after which:
 *
 * - Login attempts for the deleted account must fail
 * - Deleting an already-deleted account must not cause data leaks
 * - Another user's attempt to delete this account is denied
 * - System integrity is preserved throughout
 * - (future extension) All cascade data is confirmed erased if any other
 *   endpoints for owned data exist. Steps:
 *
 * 1. Register User A (target for deletion)
 * 2. Register User B (control)
 * 3. Authenticate as User A
 * 4. Delete User A's own account
 * 5. Assert successful deletion
 * 6. Attempt login as User A -- should fail
 * 7. Attempt to delete User A again (no error leaked / no effect)
 * 8. Authenticate as User B
 * 9. Attempt to delete User A as User B (must be denied)
 */
export async function test_api_todo_user_deletion_and_cascade(
  connection: api.IConnection,
) {
  // Register User A (will be deleted)
  const emailA = typia.random<string & tags.Format<"email">>();
  const passwordA = RandomGenerator.alphaNumeric(12);
  const joinReqA = {
    email: emailA,
    password: passwordA,
    href: "https://todo.test/signup",
    referrer: "https://todo.test/landing",
  } satisfies ITodoUser.IJoin;
  const userA: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: joinReqA },
  );
  typia.assert(userA);

  // Register User B (control)
  const emailB = typia.random<string & tags.Format<"email">>();
  const passwordB = RandomGenerator.alphaNumeric(12);
  const joinReqB = {
    email: emailB,
    password: passwordB,
    href: "https://todo.test/signup",
    referrer: "https://todo.test/landing",
  } satisfies ITodoUser.IJoin;
  const userB: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: joinReqB },
  );
  typia.assert(userB);

  // Ensure User A's token is active (the join set connection header)
  TestValidator.equals(
    "joined user token is present",
    typeof userA.token.access,
    "string",
  );

  // Delete User A's own account (using token set in connection)
  const deleted: ITodoUser = await api.functional.todo.user.users.erase(
    connection,
    { userId: userA.id },
  );
  typia.assert(deleted);
  TestValidator.equals("deleted user ID", deleted.id, userA.id);

  // Attempt to login as User A after deletion: must fail
  await TestValidator.error(
    "cannot login with deleted credentials",
    async () => {
      await api.functional.auth.user.join(
        { ...connection, headers: {} }, // bare headers to reset token
        {
          body: {
            email: emailA,
            password: passwordA,
            href: "https://todo.test/login",
            referrer: "https://todo.test/reset",
          } satisfies ITodoUser.IJoin,
        },
      );
    },
  );

  // Attempt to delete already-deleted user again (should not error/leak data)
  await TestValidator.error("no effect on double delete", async () => {
    await api.functional.todo.user.users.erase(connection, {
      userId: userA.id,
    });
  });

  // Switch to User B's context for unauthorized attempts
  await api.functional.auth.user.join(connection, {
    body: {
      email: emailB,
      password: passwordB,
      href: "https://todo.test/login",
      referrer: "https://todo.test/reset",
    } satisfies ITodoUser.IJoin,
  });

  // Attempt to delete User A (as User B, not self) -- must be denied
  await TestValidator.error(
    "cannot delete another user's account",
    async () => {
      await api.functional.todo.user.users.erase(connection, {
        userId: userA.id,
      });
    },
  );
}

