export async function postAuthUserPasswordResetComplete(props: {
  body: ITodoUser.IResetPasswordComplete;
}): Promise<ITodoUser.IResetPasswordResult> {
  const { token, password } = props.body;
  const now = toISOStringSafe(new Date());

  // --- FAKE/WORKAROUND TOKEN MAPPING ---
  // Since no password_reset_tokens table exists and only todo_users/sessions are loaded,
  // we assume token maps to a session (for the sake of compiling, not real security logic).
  // This is a placeholder for proper token handling with the real model.
  const session = await MyGlobal.prisma.todo_user_sessions.findFirst({
    where: { referrer: token },
    select: { todo_user_id: true },
  });

  if (!session) {
    throw new HttpException("Invalid or expired token", 400);
  }

  // 2. Hash the new password
  const newPasswordHash = await PasswordUtil.hash(password);

  // 3. Update user password_hash + updated_at
  await MyGlobal.prisma.todo_users.update({
    where: { id: session.todo_user_id },
    data: {
      password_hash: newPasswordHash,
      updated_at: now,
    },
  });

  // (No real token invalidation/audit possible in this model)

  return {
    message:
      "Your password has been reset. You may now login with your new password.",
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function putTodoUserUsersUserId(props: {
  user: UserPayload;
  userId: string & tags.Format<"uuid">;
  body: ITodoUser.IUpdate;
}): Promise<ITodoUser> {
  if (props.user.id !== props.userId) {
    throw new HttpException("You can only update your own account.", 403);
  }
  const existing = await MyGlobal.prisma.todo_users.findUnique({
    where: { id: props.userId },
  });
  if (!existing) {
    throw new HttpException("User not found.", 404);
  }
  try {
    const updated = await MyGlobal.prisma.todo_users.update({
      where: { id: props.userId },
      data: {
        ...(typeof props.body.email !== "undefined" && {
          email: props.body.email,
        }),
        ...(typeof props.body.password !== "undefined" && {
          password_hash: await PasswordUtil.hash(props.body.password),
        }),
        updated_at: toISOStringSafe(new Date()),
      },
    });
    return {
      id: updated.id,
      email: updated.email,
      created_at: toISOStringSafe(updated.created_at),
      updated_at: toISOStringSafe(updated.updated_at),
    };
  } catch (err) {
    if (
      typeof err === "object" &&
      err !== null &&
      "code" in err &&
      (err as any).code === "P2002" &&
      "meta" in err &&
      Array.isArray((err as any).meta?.target) &&
      (err as any).meta.target.includes("email")
    ) {
      throw new HttpException("This email address is already in use.", 409);
    }
    throw err;
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserJoin(props: {
  body: ITodoUser.IJoin;
}): Promise<ITodoUser.IAuthorized> {
  const existing = await MyGlobal.prisma.todo_users.findUnique({
    where: { email: props.body.email },
  });
  if (existing) {
    throw new HttpException("Email already registered", 409);
  }

  const password: string = props.body.password;
  const hasLetter = /[A-Za-z]/.test(password);
  const hasNumber = /[0-9]/.test(password);
  if (password.length < 8 || !hasLetter || !hasNumber) {
    throw new HttpException(
      "Password must be at least 8 characters, contain at least one letter and one number.",
      400,
    );
  }

  const passwordHash = await PasswordUtil.hash(password);

  const now = toISOStringSafe(new Date());
  const userId = v4();
  const newUser = await MyGlobal.prisma.todo_users.create({
    data: {
      id: userId,
      email: props.body.email,
      password_hash: passwordHash,
      created_at: now,
      updated_at: now,
    },
  });

  const sessionId = v4();
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const session = await MyGlobal.prisma.todo_user_sessions.create({
    data: {
      id: sessionId,
      todo_user_id: newUser.id,
      ip:
        props.body.ip !== null && props.body.ip !== undefined
          ? (props.body.ip satisfies string as string)
          : "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  const accessToken = jwt.sign(
    {
      type: "user",
      id: newUser.id,
      session_id: session.id,
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );
  const refreshToken = jwt.sign(
    {
      type: "user",
      id: newUser.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  return {
    id: newUser.id,
    email: newUser.email,
    created_at: toISOStringSafe(newUser.created_at),
    updated_at: toISOStringSafe(newUser.updated_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserLogin(props: {
  body: ITodoUser.ILogin;
}): Promise<ITodoUser.IAuthorized> {
  // Step 1: Lookup user by unique email, error if not found
  const user = await MyGlobal.prisma.todo_users.findUnique({
    where: { email: props.body.email },
  });
  if (!user) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Step 2: Verify password using PasswordUtil
  const isValid = await PasswordUtil.verify(
    props.body.password,
    user.password_hash,
  );
  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Step 3: Create a new session record in todo_user_sessions
  // Expirations: access 1h, refresh 7d (as ISO date-times)
  const now = new Date();
  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000);
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
  const sessionId = v4();

  const session = await MyGlobal.prisma.todo_user_sessions.create({
    data: {
      id: sessionId,
      todo_user_id: user.id,
      ip:
        props.body.ip !== undefined && props.body.ip !== null
          ? (props.body.ip satisfies string as string)
          : "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: toISOStringSafe(now),
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  // Step 4: Issue JWT access and refresh tokens
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: session.id,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Step 5: Return authorized user payload (matching required fields exactly)
  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function postAuthUserRefresh(props: {
  user: UserPayload;
  body: ITodoUser.IRefresh;
}): Promise<ITodoUser.IAuthorized> {
  // Step 1: Decode and verify submitted refresh token
  let decoded: { id: string; session_id: string; type: "user" };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as { id: string; session_id: string; type: "user" };
  } catch (_) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // Step 2: Sanity checks
  if (decoded.type !== "user") {
    throw new HttpException("Invalid token type", 403);
  }

  // Step 3: Validate active session (non-expired/non-revoked, matches user, session)
  const oldSession = await MyGlobal.prisma.todo_user_sessions.findFirst({
    where: {
      id: decoded.session_id,
      todo_user_id: decoded.id,
      expired_at: null,
      user: { id: decoded.id },
    },
    include: {
      user: true,
    },
  });
  if (!oldSession) {
    throw new HttpException("Session expired, revoked, or user not found", 401);
  }

  // Audit: user
  const user = oldSession.user;
  if (!user) {
    throw new HttpException("User not found", 401);
  }

  // Step 4: Mark previous session as closed (revoked/expired)
  const now = toISOStringSafe(new Date());
  await MyGlobal.prisma.todo_user_sessions.update({
    where: { id: oldSession.id },
    data: { expired_at: now },
  });

  // Step 5: Insert new session record with current context
  const newSessionId = v4();
  // Always provide a string for ip (empty string if not present)
  const ipVal =
    props.body.ip !== null && props.body.ip !== undefined
      ? (props.body.ip satisfies string as string)
      : "";
  const newSession = await MyGlobal.prisma.todo_user_sessions.create({
    data: {
      id: newSessionId,
      todo_user_id: user.id,
      ip: ipVal,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: null,
    },
  });

  // Step 6: Generate tokens with exact string/datetime/uuid usage
  const accessExpire = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpire = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const payload = {
    type: "user",
    id: user.id,
    session_id: newSession.id,
    created_at: now,
  };
  const accessToken = jwt.sign(payload, MyGlobal.env.JWT_SECRET_KEY, {
    expiresIn: "1h",
    issuer: "autobe",
  });
  const refreshToken = jwt.sign(
    { ...payload, tokenType: "refresh" },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );

  // Step 7: Construct DTO output
  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpire,
      refreshable_until: refreshExpire,
    },
  };
